using System.Globalization;
using System.Text.Json;
using FinanceLogistics.Application.Imports;
using FinanceLogistics.Infrastructure.Imports;
namespace FinanceLogistics.Infrastructure.LogisticsTrade;
public sealed record TradeRawPayload(string Kind,PoCellDto[] Cells);
public static class TradeSourcePolicy {
 public static TradeSourceProfile TemplateProfile(string source,string json){using var d=JsonDocument.Parse(json);var r=d.RootElement;var p=TradeSourceProfiles.Get(source,r.GetProperty("profile").GetString()??"");if(r.GetProperty("schemaVersion").GetInt32()!=p.SchemaVersion
    ||r.GetProperty("sheet").GetString()!=p.Sheet
    ||(r.TryGetProperty("headerRow",out var headerRow)?headerRow.GetInt32():1)!=p.HeaderRow
    ||r.GetProperty("headerPolicy").GetString()!="EXACT_NAMES"
    ||r.GetProperty("formulaPolicy").GetString()!=p.FormulaPolicy
    ||(p.RaPaymentOutputOnly && (!r.TryGetProperty("paymentFieldPolicy",out var paymentPolicy)||paymentPolicy.GetString()!="RA_ONLY")))throw new FormatException("Template/profile mismatch.");return p;}
 public static bool Supports(TradeSourceProfile p,string json){try{return TemplateProfile(p.SourceCode,json).SourceCode==p.SourceCode;}catch(Exception e)when(e is JsonException or KeyNotFoundException or InvalidOperationException or FormatException or PoImportFault){return false;}}
 public static TradeSourceProfile ProfileFromFrozen(string source,string json){using var d=JsonDocument.Parse(json);return TradeSourceProfiles.Get(source,d.RootElement.GetProperty("profile").GetString()??"");}
 private static void Validate(string mode,DateOnly start,DateOnly end,int max,TradeSourceProfile p){if(max is <1 or >TradeSourceProfiles.MaxRows||end<=start||end.DayNumber-start.DayNumber>3660||p.IsVerbatim&&mode!="AS_OF_SNAPSHOT"||!p.IsVerbatim&&mode is not("SELECTED_MONTH" or "YEAR_TO_PERIOD" or "EXPLICIT_RANGE"))throw new FormatException("Unsupported policy.");}
 public static TradeParsePolicy Resolve(string json,DateOnly periodStart,DateOnly periodEnd,TradeSourceProfile p){try{var limits=PoProfile.Limits(json);using var d=JsonDocument.Parse(json);var r=d.RootElement;if(r.GetProperty("coverageProperty").GetString()!=p.CoverageProperty||r.GetProperty("dateTextCentury").GetInt32()!=2000)throw new FormatException();var mode=r.GetProperty("logisticsPeriodMode").GetString()!;var start=mode switch{"SELECTED_MONTH" or "AS_OF_SNAPSHOT"=>periodStart,"YEAR_TO_PERIOD"=>new DateOnly(periodStart.Year,1,1),"EXPLICIT_RANGE"=>DateOnly.ParseExact(r.GetProperty("coverageStart").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture),_=>throw new FormatException()};var end=mode=="EXPLICIT_RANGE"?DateOnly.ParseExact(r.GetProperty("coverageEndExclusive").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture):periodEnd;Validate(mode,start,end,limits.Rows,p);return new(mode,start,end,true,limits.Rows);}catch(Exception e)when(e is JsonException or KeyNotFoundException or InvalidOperationException or FormatException or ArgumentException){throw new PoImportFault(409,"TRADE_PERIOD_POLICY_REQUIRED","Cần cấu hình phạm vi nguồn/kỳ; Pin Test dùng snapshot không lọc ngày chứng nhận.");}}
 public static TradeParsePolicy Frozen(string json,TradeSourceProfile p){using var d=JsonDocument.Parse(json);var r=d.RootElement;if(r.GetProperty("sourceCode").GetString()!=p.SourceCode||r.GetProperty("scopeCode").GetString()!=p.ScopeCode||r.GetProperty("profile").GetString()!=p.Code||r.GetProperty("coverageProperty").GetString()!=p.CoverageProperty||r.GetProperty("dateTextCentury").GetInt32()!=2000||!r.GetProperty("allowCachedAmountFormulas").GetBoolean()||r.GetProperty("formulaPolicy").GetString()!=p.FormulaPolicy||TemplateProfile(p.SourceCode,r.GetProperty("templateDefinition").GetRawText()).Code!=p.Code)throw new InvalidOperationException("Frozen profile mismatch.");var mode=r.GetProperty("periodMode").GetString()!;var start=DateOnly.ParseExact(r.GetProperty("startDate").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture);var end=DateOnly.ParseExact(r.GetProperty("endDateExclusive").GetString()!,"yyyy-MM-dd",CultureInfo.InvariantCulture);var max=r.GetProperty("maxRows").GetInt32();Validate(mode,start,end,max,p);return new(mode,start,end,true,max);}
}
